4	export function expectPatchError(doc, patch, message, index) {
5	  let thrown;
6	  try {
7	    applyPatch(doc, patch);
8	  } catch (err) {
9	    thrown = err;
10	  }
11	  assert.notStrictEqual(thrown, undefined, 'expected applyPatch to throw');
12	  assert.ok(thrown instanceof PatchError, 'instanceof PatchError');
13	  assert.ok(thrown instanceof Error, 'instanceof Error');
14	  assert.strictEqual(thrown.name, 'PatchError');
15	  assert.strictEqual(thrown.message, message);
16	  assert.strictEqual(thrown.index, index);
17	}
18	
19	export function expectOpError(doc, op, reason) {
20	  expectPatchError(doc, [op], `operation 0: ${reason}`, 0);
21	}
22	
23	export function deepClone(v) {
24	  if (Array.isArray(v)) return v.map(deepClone);
25	  if (v !== null && typeof v === 'object') {
26	    const out = {};
27	    for (const k of Object.keys(v)) {
28	      Object.defineProperty(out, k, {
29	        value: deepClone(v[k]),
30	        writable: true,
31	        enumerable: true,
32	        configurable: true,
33	      });
34	    }
35	    return out;
36	  }
37	  return v;
38	}
39	
40	export function collectObjects(v, set = new Set()) {
41	  if (v !== null && typeof v === 'object' && !set.has(v)) {
42	    set.add(v);
43	    for (const k of Object.keys(v)) collectObjects(v[k], set);
44	  }
45	  return set;
46	}
