56	// Valid JSON '[]' padded with spaces so the result is exactly `total` bytes
57	// (BOM included when withBom is true).
58	export function padded(total, withBom = false) {
59	  const head = withBom ? Buffer.concat([BOM, Buffer.from('[]')]) : Buffer.from('[]');
60	  return Buffer.concat([head, Buffer.alloc(total - head.length, 0x20)]);
61	}
62	
63	export function nestedArrays(depth) {
64	  return '['.repeat(depth) + ']'.repeat(depth);
65	}
